  for(const run of lo.match(/[\u0E01-\u0E4E]+/g)||[]){const n=run.length,dp=[[0,0,-1,0,0]];let SB=null;try{if(typeof TN!=="undefined"){SB=new Set([0,n]);for(const y of TN.seg(run)){SB.add(y.i);SB.add(y.i+y.n)}}}catch(_){SB=null}
    for(let e=1;e<=n;e++){let best=[dp[e-1][0]+1,dp[e-1][1]+1,e-1,0,dp[e-1][4]+1];
      for(let b=Math.max(0,e-NMAX);b<e-1;b++){const t=run.slice(b,e);if(!isW(t)||(SB&&!(SB.has(b)&&SB.has(e)))||(hw&&t.length>hw.length&&t.includes(hw))||bad.test(t)||(e<n&&bad.test(run[e]))||(b>0&&/[\u0E40-\u0E44]/.test(run[b-1])))continue;const c=[dp[b][0],dp[b][1]+1,b,1,dp[b][4]+(e-b)*(e-b)];if(c[0]<best[0]||(c[0]===best[0]&&(c[1]<best[1]||(c[1]===best[1]&&c[4]<best[4]))))best=c}
      dp[e]=best}
    const toks=[];for(let e=n;e>0;e=dp[e][2])if(dp[e][3])toks.unshift(run.slice(dp[e][2],e));
    for(const t of toks)if(NDICT[t]!==undefined&&t.length>=2&&!seen.has(t)&&!(hw&&(hw.includes(t)||t.includes(hw)))){seen.add(t);out.push(t)}}
  
  /* RYU v12.77: note every known word (easy ones too), in sentence order; if it would pass ~2 lines, drop the most common words first */
  const wd=t=>t.length*0.62+[...((NRD[t]?" "+NRD[t]:"")+"("+NDICT[t]+")")].reduce((a,c)=>a+(/[\uAC00-\uD7A3]/.test(c)?1:0.55),0)+1.6;
  const cap=(typeof isBig==="function"&&isBig())?140:60;let tot=out.reduce((a,t)=>a+wd(t),0);
