const hlSyl=(e,i,w)=>{try{if(typeof TN==="undefined")return true;const m=/[\u0E01-\u0E4E]+/g;let r;while((r=m.exec(e))){if(i>=r.index&&i<r.index+r[0].length){const bs=new Set([0]);for(const y of TN.seg(r[0])){bs.add(y.i);bs.add(y.i+y.n)}return bs.has(i-r.index)&&bs.has(i-r.index+w.length)}}}catch(_){}return true};
const hlBad=(e,i,w)=>{const nx=e[i+w.length]||"",pv=e[i-1]||"";if(!hlSyl(e,i,w))return true;if(/[\u0E30-\u0E3A\u0E45-\u0E4E]/.test(nx)||/[\u0E40-\u0E44]/.test(pv))return true;for(let L=w.length+1;L<=Math.min(NMAX,e.length-i);L++){const k=e.slice(i,i+L);if(NDICT[k]!==undefined&&!/[\u0E30-\u0E3A\u0E45-\u0E4E]/.test(e[i+L]||"")&&e.indexOf(w,i+1)>=0)return true}return false};
