function keyOf(it){if(!AUD||it.noAud)return null;let k=akey(it.text);if(it.ko)k="k_"+k;else if(!FVS.has(it.text)&&(it.m||MVS.has(it.text))&&AUD["m_"+k])k="m_"+k;return AUD[k]?k:null}
function blobUrl(k){if(ABLOB[k])return Promise.resolve(ABLOB[k]);if(BLOBP[k])return BLOBP[k];
  return BLOBP[k]=fetch(aurl(k)).then(r=>{if(!r.ok)throw 0;return r.blob()}).then(b=>ABLOB[k]=URL.createObjectURL(b)).catch(e=>{delete BLOBP[k];throw e})}
let LT=null;function loadStart(){clearTimeout(LT);LT=setTimeout(()=>{P.loading=true;showPlayer()},350)}
function loadDone(){clearTimeout(LT);if(P.loading){P.loading=false;showPlayer()}}
setTimeout(()=>{if(AUD){blobUrl("_gap150").catch(()=>{});blobUrl("_gap450").catch(()=>{});blobUrl("_gap900").catch(()=>{})}},1500);
/* v2.76 RYU: the same sentence again = short pause only */
function gapMs(it){const q=P.queue;if(P.i>=q.length||(q[P.i].rv&&q[P.i].rv0===P.i))return 900;let j=P.i;if(!SAYKO)while(j<q.length&&q[j].ko)j++;const n=q[j];return n&&!it.ko&&!n.ko&&n.text===it.text?150:450}
function gapThen(tok,ms){const a=aud();let fired=false;const fb=()=>{if(fired)return;fired=true;a.onended=a.onerror=null;setTimeout(()=>nextPlay(tok),ms)};
  if(tok!==P.token)return;a.onended=()=>{if(fired)return;fired=true;a.onended=a.onerror=null;nextPlay(tok)};a.onerror=fb;
  try{a.src=ABLOB["_gap"+ms]||("audio/_gap"+ms+".mp3");a.playbackRate=1;a.defaultPlaybackRate=1;const pr=a.play();if(pr&&pr.catch)pr.catch(fb)}catch(e){fb()}}
function msMeta(it){if(!("mediaSession" in navigator))return;try{
  navigator.mediaSession.metadata=new MediaMetadata({title:it.ko?koSay(it.text):rep(it.text),artist:"THAI Lang",artwork:[{src:"icon-512.png",sizes:"512x512",type:"image/png"}]});
  if(!msMeta._h){msMeta._h=1;const ms=navigator.mediaSession;
    ms.setActionHandler("pause",()=>setPaused(true));
    ms.setActionHandler("play",()=>setPaused(false));
    try{ms.setActionHandler("stop",()=>stopPlay())}catch(e){}
    try{ms.setActionHandler("nexttrack",()=>{if(!P.active)return;const tok=P.token;try{aud().pause()}catch(e){}P.k=0;P.i++;nextPlay(tok)})}catch(e){}
    try{ms.setActionHandler("previoustrack",()=>{if(!P.active)return;const tok=P.token;try{aud().pause()}catch(e){}P.k=0;P.i=Math.max(0,P.i-1);nextPlay(tok)})}catch(e){}}
  navigator.mediaSession.playbackState="playing"}catch(e){}}
/* single item: repeat forever. list: each item REP times, then next; after the last, start over */
/* tap one line while a list is playing: loop that line; the bottom "▶ 재생" button moves on to the next one */
/* word cards while playing (RYU v2.5): the meaning side shows only while the Korean meaning is spoken; every Lao play shows the word side */
function cardSync(it){const prev=P.cardKey;let key=null,flip=false;
  if(it&&it.id&&String(it.id).startsWith("cd-")){const el=document.getElementById(it.id);const f=el&&el.querySelector("[data-flip]");key=f?f.dataset.flip:null;
    if(key){P.lastGi=it.gi;P.lastRound=P.round;flip=!!it.ko}}
  let ch=false;
  if(prev&&prev!==key&&S.flipped[prev]){delete S.flipped[prev];ch=true}
  if(key&&!!S.flipped[key]!==flip){if(flip)S.flipped[key]=true;else delete S.flipped[key];ch=true}
  P.cardKey=key;if(ch){const y=scrollY;render();if(scrollY!==y)scrollTo(0,y);if(P.hold!=null)holdMark(P.hold);else if(P.single&&P.active)holdMark(P.i)}}
function holdMark(idx){document.querySelectorAll(".speak.hold").forEach(b=>b.classList.remove("hold"));try{if(document.activeElement&&document.activeElement.blur)document.activeElement.blur()}catch(e){}
  const it=idx!=null&&P.queue[idx];const el=it&&document.getElementById(it.id);const b=el&&(el.querySelector(".card-foot [data-say]")||el.querySelector("[data-say]"));if(b)b.classList.add("hold")}
function holdAt(idx){const tok=++P.token;try{aud().pause()}catch(e){}try{if(hasSS)speechSynthesis.cancel()}catch(e){}
  P.paused=false;P._resume=null;P.hold=idx;P.i=idx;P.k=0;holdMark(idx);nextPlay(tok)}
function releaseHold(){const it=P.queue[P.hold];const tok=++P.token;try{aud().pause()}catch(e){}try{if(hasSS)speechSynthesis.cancel()}catch(e){}
  P.hold=null;holdMark(null);P.paused=false;P._resume=null;P.k=0;P.i=it?it.ge+1:P.i+1;nextPlay(tok)}
function advQ(){if(P.hold!=null){P.i=P.hold;P.k++;return}const it=P.queue[P.i];if(!it){P.i++;return}/* Enter released the loop: go on to the next item */if(P.rel){P.rel=0;P.k=0;P.i=it.ge+1;return}if(P.i<it.ge){P.i++;return}
  if(it.rv){P.k=0;if(it.rvl&&(P.rk||0)<REP-1){P.rk=(P.rk||0)+1;P.i=it.rv0}else{if(it.rvl)P.rk=0;P.i++}return}
  if(P.single||P.k<(it.kg?REP-2:REP-1)){P.k++;P.i=it.rs;return}P.k=0;P.i=it.ge+1}
function nextPlay(tok){
  if(tok!==P.token)return;if(P.paused){P._resume=()=>nextPlay(tok);return}
  if(P.i>=P.queue.length){if(P.chain){chainNext();return}P.round++;P.i=0}
  const it=P.queue[P.i];if(it.ko&&!SAYKO){advQ();nextPlay(tok);return}cardSync(it);mark(it.id);showPlayer();
  if(AUD&&!it.noAud){const k=keyOf(it);if(k){const a=aud();let done=false;
    const fin=()=>{if(done||tok!==P.token)return;done=true;a.onended=a.onerror=null;advQ();gapThen(tok,gapMs(it))};
    a.onended=fin;a.onerror=()=>{if(done||tok!==P.token)return;done=true;it.noAud=1;nextPlay(tok)};
    const go=src=>{if(tok!==P.token)return;loadDone();try{a.src=src;a.playbackRate=RATE;a.defaultPlaybackRate=RATE;const pr=a.play();if(pr&&pr.catch)pr.catch(e=>{if(tok!==P.token)return;if(e&&e.name==="NotAllowedError"){stopPlay();ttsWarn();return}a.onerror()})}catch(e){a.onerror()}};
    msMeta(it);if(ABLOB[k])go(ABLOB[k]);else{loadStart();blobUrl(k).then(go,()=>go(aurl(k)))}
    for(let j=1;j<=3;j++){const nx=P.queue[P.i+j];const nk=nx&&keyOf(nx);if(nk)blobUrl(nk).catch(()=>{})}
    return}}
  if(!hasSS){P.i++;setTimeout(()=>nextPlay(tok),50);return}
  try{const u=utterOf(it);
    let done=false;const t0=Date.now();const fin=()=>{clearInterval(wd);if(done||tok!==P.token)return;done=true;advQ();setTimeout(()=>nextPlay(tok),gapMs(it))};
    u.onstart=()=>{P.err=0};
    u.onend=fin;u.onerror=ev=>{const er=ev&&ev.error;if(er==="interrupted"||er==="canceled"){fin();return}
      if(tok!==P.token)return;P.err=(P.err||0)+1;if(er==="not-allowed"||P.err>=3){stopPlay();ttsWarn();return}fin()};
    const wd=setInterval(()=>{if(tok!==P.token){clearInterval(wd);return}let busy=true;try{busy=speechSynthesis.speaking||speechSynthesis.pending}catch(e){}
      const lim=(4000+u.text.length*220)/RATE;if((!busy&&Date.now()-t0>1200)||Date.now()-t0>lim)fin()},400);
    try{speechSynthesis.resume()}catch(e){}speechSynthesis.speak(u)}catch(e){stopPlay()}
}
if(hasSS){try{speechSynthesis.getVoices();speechSynthesis.addEventListener("voiceschanged",loadVoices)}catch(e){}}
loadVoices();
function setSayKo(v){SAYKO=!!v;store.set("tha-sayko",SAYKO);const c=document.getElementById("koChk");if(c)c.checked=SAYKO}
{const c=document.getElementById("koChk");if(c){c.checked=SAYKO;c.addEventListener("change",()=>{setSayKo(c.checked);try{c.blur()}catch(e){}})}}
$("#repSel").addEventListener("change",e=>{REP=+e.target.value;store.set("tha-rep",REP);showPlayer()});
$("#rateSel").addEventListener("change",e=>{RATE=+e.target.value;store.set("tha-rate",RATE);try{if(AEL){AEL.playbackRate=RATE}}catch(x){}});
const koSay=t=>String(t).replace(/[\u2460-\u2473]/g,"").replace(/\s*\([^)]*\)/g,"").replace(/[;·]/g,",").replace(/\s+/g," ").trim()||String(t);
const koOf=id=>{const m=/^(?:cd|eh)-(.+)-(\d+)$/.exec(id||"");const w=m&&B[m[1]]&&B[m[1]].w[+m[2]];if(w)return w[3];const el=id&&document.getElementById(id),k=el&&el.querySelector(".ko");return k?k.textContent:""};
const isM=id=>{id=id||"";if(/^ln-.*-1$/.test(id))return true;const m=/^dl-.*-(\d+)$/.exec(id);return !!(m&&m[1]%2)};
const sayItem=el=>{const b=el.querySelector("[data-say]");return b?{text:b.dataset.say,rd:b.dataset.rd,id:el.id,m:isM(el.id)}:null};

function save(){S.lastSub[S.part]=S.sub;store.set("tha-sel",{part:S.part,sub:S.sub,mode:S.mode,bun:S.bun,lastSub:S.lastSub})}

/* ---------- render ---------- */
function renderTop(){
  const all=Object.values(B).filter(b=>!b.info),nw=all.reduce((n,b)=>n+b.w.length,0),kn=Object.keys(known).length;
  const bs=b=>b.w.reduce((m,w)=>m+w[4].length,0)+b.pr.length*2+b.dl.length+(b.sm&&b.sm[0]?1:0);const ns=all.reduce((n,b)=>n+bs(b),0);
  $("#stats").innerHTML=`<span><b>${all.length}</b>묶음</span><span><b>${nw.toLocaleString()}</b>단어</span><span><b>${ns.toLocaleString()}</b>문장</span>`;
  $("#groups").innerHTML=PARTS.map(p=>`<button class="group" data-g="${p.id}" data-part="${p.id}" aria-pressed="${p.id===S.part}"><i></i>${esc(p.ko)} <small>${p.subs.reduce((n,s)=>n+s.b.length,0)}</small></button>`).join("");
  const p=PARTS.find(p=>p.id===S.part);
  $("#subs").innerHTML=p.subs.map(s=>`<button class="sub" role="tab" data-sub="${s.id}" aria-selected="${s.id===S.sub}"><span class="code">${esc(s.code.split("-")[1])}</span><span class="name">${esc(s.name)}</span></button>`).join("");
  {const cs=SUBS[S.sub]||p.subs[0],nsb=cs.b.reduce((m,id)=>m+bs(B[id]),0);const nwd=cs.b.reduce((m,id)=>m+B[id].w.length,0);$("#sinfo").innerHTML=`<b>[${esc(cs.code)}]</b> ${esc(cs.name)} · ${cs.b.length}묶음`+(B[cs.b[0]].info?"":` ${nwd.toLocaleString()}단어 ${nsb.toLocaleString()}문장`)}
  $("#app").dataset.g=S.part;
}
